"""Typed ``skill.md`` frontmatter.

:class:`SkillFrontmatter` is the authoring contract for the YAML block above
the markdown body. The compiler validates a mapping into this model before it
compiles behaviour, and the published JSON Schema is generated from the same
class. Skill-level ``requires`` is not a field: that key is rejected so it
cannot reappear in the schema.
"""

from __future__ import annotations

from typing import Any, Literal

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    RootModel,
    ValidationInfo,
    field_validator,
    model_validator,
)
from pydantic import ValidationError as PydanticValidationError

from rasa.exceptions import ValidationError
from rasa.mantle.skills.conditions import REQUIRES_FIELD, UTTER_ON_ACTIVATE_VALUE

_INVALID_FRONTMATTER_CODE = "skill.markdown.invalid_frontmatter"
_UNKNOWN_FRONTMATTER_KEY_CODE = "skill.markdown.unknown_frontmatter_key"
_INVALID_TOOL_CONSTRAINTS_CODE = "skill.markdown.invalid_tool_constraints"
_INVALID_UTTER_CODE = "skill.markdown.invalid_utter"
_INVALID_KNOWLEDGE_ANSWERING_CODE = "skill.markdown.invalid_knowledge_answering"
_INVALID_IMPORT_TOOLS_CODE = "skill.markdown.invalid_import_tools"
_INVALID_ROUTING_CODE = "skill.markdown.invalid_routing"
_COMPLETE_WHEN_INVALID_CODE = "skill.complete_when.invalid"
_INVALID_PRECONDITION_CODE = "skill.precondition.invalid"
_INVALID_BOOLEAN_FRONTMATTER_CODE = "skill.markdown.invalid_boolean_frontmatter"
_SKILL_LEVEL_REQUIRES_REMOVED_CODE = "skill.requires.removed"

_FIELD_CODES = {
    "tool_constraints": _INVALID_TOOL_CONSTRAINTS_CODE,
    "utter": _INVALID_UTTER_CODE,
    "complete_when": _COMPLETE_WHEN_INVALID_CODE,
    "knowledge_answering": _INVALID_KNOWLEDGE_ANSWERING_CODE,
    "import_tools": _INVALID_IMPORT_TOOLS_CODE,
    "routing": _INVALID_ROUTING_CODE,
    "precondition": _INVALID_PRECONDITION_CODE,
    "hidden": _INVALID_BOOLEAN_FRONTMATTER_CODE,
    "disabled": _INVALID_BOOLEAN_FRONTMATTER_CODE,
    "always_include_in_prompt": _INVALID_BOOLEAN_FRONTMATTER_CODE,
}

_TOOL_CONSTRAINT_KEYS = (
    "requires",
    "requires_confirmation",
    "on_success",
    "on_failure",
)
_CONFIRMATION_KEYS = (
    "enabled",
    "utter_for_confirmation",
    "utter_on_user_denial",
)


class RequiresConfirmationDocument(BaseModel):
    """Confirmation gate under a tool constraint.

    ``enabled`` turns the pause on. ``utter_for_confirmation`` and
    ``utter_on_user_denial`` name responses in ``responses.yml``. Omit a name
    to leave that line to the model.
    """

    model_config = ConfigDict(extra="forbid", frozen=True)

    enabled: bool = False
    utter_for_confirmation: str | None = None
    utter_on_user_denial: str | None = None

    @field_validator("utter_for_confirmation", "utter_on_user_denial", mode="before")
    @classmethod
    def _confirmation_strings(cls, value: Any) -> Any:
        """Reject numbers and other non-strings; YAML must quote response names."""
        return _reject_non_string(value)

    @field_validator("enabled", mode="before")
    @classmethod
    def _strict_enabled(cls, value: Any) -> Any:
        """Reject YAML strings; only a real boolean enables the gate."""
        if not isinstance(value, bool):
            raise ValueError("enabled must be a boolean")
        return value


class ToolConstraintOptions(BaseModel):
    """Options for one tool under ``tool_constraints``."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    requires: str | None = None
    requires_confirmation: RequiresConfirmationDocument | None = None
    on_success: str | None = None
    on_failure: str | None = None

    @field_validator("requires", "on_success", "on_failure", mode="before")
    @classmethod
    def _constraint_strings(cls, value: Any) -> Any:
        """Reject numbers and other non-strings before they become text."""
        return _reject_non_string(value)

    @model_validator(mode="before")
    @classmethod
    def _reject_null_confirmation(cls, value: Any) -> Any:
        """Fail a bare ``requires_confirmation:`` instead of disabling the gate."""
        if (
            isinstance(value, dict)
            and "requires_confirmation" in value
            and value["requires_confirmation"] is None
        ):
            raise ValueError("requires_confirmation must be a mapping")
        return value


class ToolConstraintEntry(RootModel[dict[str, ToolConstraintOptions]]):
    """One ``tool_constraints`` item: a single tool name mapped to its options."""

    model_config = ConfigDict(
        json_schema_extra={"maxProperties": 1, "minProperties": 1}
    )

    @model_validator(mode="before")
    @classmethod
    def _single_tool(cls, value: Any) -> Any:
        """Coerce a bare tool name and reject multi-key entries."""
        return _single_key_mapping(value, label="tool_constraints")


class CompleteWhenFrontmatter(BaseModel):
    """Skill-level ``complete_when`` mapping (``condition`` and/or ``criteria``)."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    condition: str | None = None
    criteria: list[str] = Field(default_factory=list)

    @field_validator("condition", mode="before")
    @classmethod
    def _condition_string(cls, value: Any) -> Any:
        """Reject a non-string condition before it is coerced to text."""
        return _reject_non_string(value)

    @field_validator("criteria", mode="before")
    @classmethod
    def _criteria_strings(cls, value: Any) -> Any:
        """Reject a criteria entry that is not a string."""
        return _reject_non_string_items(value)

    @model_validator(mode="before")
    @classmethod
    def _require_mapping(cls, value: Any) -> Any:
        """Reject a bare string; skill-level completion is always a mapping."""
        if value is None or isinstance(value, dict):
            return value
        raise ValueError(
            "complete_when must be a mapping with 'condition' and/or 'criteria' "
            "(bare strings are not allowed)."
        )


class SkillKnowledgeAnsweringFrontmatter(BaseModel):
    """Skill-level answering guidance under ``knowledge_answering``."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    instructions: str | None = None

    @field_validator("instructions", mode="before")
    @classmethod
    def _instructions_string(cls, value: Any) -> Any:
        """Reject a non-string instructions value."""
        return _reject_non_string(value)


class SkillRoutingFrontmatter(BaseModel):
    """Engine routing flags under ``routing``."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    is_default: bool = False
    engine_managed: bool = False


class UtterTriggerOptions(BaseModel):
    """When one ``utter`` response fires (``on: activate`` and/or ``when``)."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    on: Literal["activate"] | None = None
    when: str | None = None

    @field_validator("when", mode="before")
    @classmethod
    def _when_string(cls, value: Any) -> Any:
        """Reject a non-string condition before it is coerced to text."""
        return _reject_non_string(value)

    @model_validator(mode="before")
    @classmethod
    def _normalize_yaml_on_key(cls, value: Any) -> Any:
        """Rewrite YAML 1.1 boolean ``on`` and reject unsupported values.

        Unquoted ``on:`` loads as the boolean key ``True``. ``on: activate``
        therefore arrives as ``{True: "activate"}``.
        """
        if not isinstance(value, dict):
            return value
        data = dict(value)
        if True in data and "on" not in data:
            data["on"] = data.pop(True)
        if "on" in data and data["on"] is None:
            data["on"] = UTTER_ON_ACTIVATE_VALUE
        if "on" in data and data["on"] != UTTER_ON_ACTIVATE_VALUE:
            raise ValueError(f"unsupported on: value {data['on']!r}")
        return data


class UtterTriggerEntry(RootModel[dict[str, UtterTriggerOptions]]):
    """One ``utter`` item: a response name mapped to its trigger options."""

    model_config = ConfigDict(
        json_schema_extra={"maxProperties": 1, "minProperties": 1}
    )

    @model_validator(mode="before")
    @classmethod
    def _single_response(cls, value: Any) -> Any:
        """Reject entries that are not a single response-name mapping."""
        return _single_key_mapping(value, label="utter")


class SkillFrontmatter(BaseModel):
    """Authoring shape of ``skill.md`` YAML frontmatter.

    Supported keys only. Skill-level ``requires`` is rejected before
    validation so it is not part of this contract.
    """

    model_config = ConfigDict(extra="forbid", frozen=True, title="skill.md frontmatter")

    name: str | None = None
    description: str | None = None
    precondition: str | None = None
    hidden: bool = False
    disabled: bool = False
    always_include_in_prompt: bool = False
    complete_when: CompleteWhenFrontmatter | None = None
    import_tools: list[str] = Field(default_factory=list)
    tool_constraints: list[ToolConstraintEntry] = Field(default_factory=list)
    utter: list[UtterTriggerEntry] = Field(default_factory=list)
    knowledge_answering: SkillKnowledgeAnsweringFrontmatter | None = None
    routing: SkillRoutingFrontmatter = Field(default_factory=SkillRoutingFrontmatter)

    @field_validator("name", "description", mode="before")
    @classmethod
    def _optional_string(cls, value: Any) -> Any:
        """Keep display fields as strings when they are set."""
        if value is None:
            return None
        if not isinstance(value, str):
            raise ValueError("must be a string")
        return value

    @field_validator("precondition", mode="before")
    @classmethod
    def _non_empty_precondition(cls, value: Any) -> Any:
        """Normalize a semantic precondition name."""
        if value is None:
            return None
        if not isinstance(value, str) or not value.strip():
            raise ValueError(
                "precondition must be a non-empty semantic name string, "
                f"got {type(value).__name__}."
            )
        return value.strip()

    @field_validator("hidden", "disabled", "always_include_in_prompt", mode="before")
    @classmethod
    def _strict_bool(cls, value: Any, info: ValidationInfo) -> Any:
        """Reject YAML strings and integers; only real booleans are accepted."""
        if value is None:
            return False
        if not isinstance(value, bool):
            raise ValueError(f"'{info.field_name}' must be a boolean.")
        return value

    @field_validator("routing", mode="before")
    @classmethod
    def _null_routing(cls, value: Any) -> Any:
        """Treat an explicit null ``routing`` block as empty flags."""
        if value is None:
            return {}
        return value

    @field_validator("import_tools", "tool_constraints", "utter", mode="before")
    @classmethod
    def _null_list(cls, value: Any) -> Any:
        """Treat an explicit null list as omitted."""
        if value is None:
            return []
        return value

    @field_validator("import_tools", mode="before")
    @classmethod
    def _import_tool_strings(cls, value: Any) -> Any:
        """Reject an import entry that is not a string."""
        if value is None:
            return value
        return _reject_non_string_items(value)


def parse_skill_frontmatter(raw: Any) -> SkillFrontmatter:
    """Validate a frontmatter mapping into :class:`SkillFrontmatter`.

    Args:
        raw: Parsed YAML frontmatter.

    Returns:
        The validated authoring model.

    Raises:
        ValidationError: When ``requires`` is present, the value is not a
            mapping, or a field does not match the model.
    """
    if not isinstance(raw, dict):
        raise ValidationError(
            code=_INVALID_FRONTMATTER_CODE,
            event_info="skill.md frontmatter must be a YAML mapping.",
        )
    if REQUIRES_FIELD in raw:
        raise ValidationError(
            code=_SKILL_LEVEL_REQUIRES_REMOVED_CODE,
            event_info=(
                "Skill-level requires is no longer supported. Use precondition to "
                "park the skill until a resolver runs, or hidden: true to omit it "
                "from routing. Tool-level requires under tool_constraints is "
                "unchanged."
            ),
        )
    try:
        return SkillFrontmatter.model_validate(raw)
    except PydanticValidationError as exc:
        raise _frontmatter_validation_error(exc) from exc


def _reject_non_string(value: Any) -> Any:
    """Return a string or null, and reject values Pydantic would coerce."""
    if value is None or isinstance(value, str):
        return value
    raise ValueError("must be a string")


def _reject_non_string_items(value: Any) -> Any:
    """Return a list unchanged, rejecting any item that is not a string."""
    if not isinstance(value, list):
        return value
    for item in value:
        if not isinstance(item, str):
            raise ValueError("must be a string")
    return value


def _single_key_mapping(value: Any, *, label: str) -> Any:
    """Return a one-key mapping, coercing a null value to an empty options map."""
    if not isinstance(value, dict) or len(value) != 1:
        raise ValueError(f"Each {label} entry must be a single-key mapping.")
    name, config = next(iter(value.items()))
    if not isinstance(name, str) or not name:
        raise ValueError(f"Each {label} entry must use a non-empty string key.")
    if config is None:
        return {name: {}}
    if not isinstance(config, dict):
        raise ValueError(f"{label} options for {name!r} must be a mapping.")
    return value


def _frontmatter_validation_error(exc: PydanticValidationError) -> ValidationError:
    """Map a Pydantic error onto a :class:`ValidationError` that names the key."""
    error = exc.errors()[0]
    loc = error.get("loc", ())
    if error.get("type") in {"extra_forbidden", "invalid_key"} and (
        not loc or loc[0] not in _FIELD_CODES or loc[0] == "routing"
    ):
        code = _UNKNOWN_FRONTMATTER_KEY_CODE
    elif loc:
        code = _FIELD_CODES.get(str(loc[0]), _INVALID_FRONTMATTER_CODE)
    else:
        code = _INVALID_FRONTMATTER_CODE
    return ValidationError(code=code, event_info=_format_frontmatter_error(error))


def _format_frontmatter_error(error: dict[str, Any]) -> str:
    """Return a message that names the rejected key."""
    loc = error.get("loc", ())
    key = loc[-1] if loc else "unknown"
    if error.get("type") in {"extra_forbidden", "invalid_key"}:
        if loc and loc[0] == "complete_when":
            return f"unknown keys: {key}"
        if loc and loc[0] == "tool_constraints" and "requires_confirmation" not in loc:
            allowed = ", ".join(_TOOL_CONSTRAINT_KEYS)
            return f"Unknown key(s): {key}. Allowed keys: {allowed}."
        if loc and "requires_confirmation" in loc:
            allowed = ", ".join(_CONFIRMATION_KEYS)
            return f"Unknown key(s): {key}. Allowed keys: {allowed}."
        return f"Unknown key(s): {key}"
    message = str(error.get("msg", "invalid frontmatter"))
    loc_text = ".".join(str(part) for part in loc)
    if loc_text and loc_text not in message:
        return f"{loc_text}: {message}"
    return message
